let magnets = [];
let dragged = null;

function setup() {
  createCanvas(800, 600);
  rectMode(CENTER);
  textAlign(CENTER, CENTER);
  for (let i = 0; i < 6; i++) {
    magnets.push(new Magnet(random(150, width - 150), random(150, height - 150), random(TWO_PI)));
  }
}

function draw() {
  background(30, 32, 40);

  for (let i = 0; i < magnets.length; i++) {
    for (let j = i + 1; j < magnets.length; j++) {
      applyMagnetism(magnets[i], magnets[j]);
    }
  }

  for (let m of magnets) {
    if (m !== dragged) {
      m.update();
    }
    m.display();
  }

  fill(240);
  noStroke();
  textSize(14);
  text("Bouncy Magnets: Click and drag to move, press SPACE to add magnet", width / 2, 25);
}

function applyMagnetism(m1, m2) {
  let p1 = [m1.getNorth(), m1.getSouth()];
  let p2 = [m2.getNorth(), m2.getSouth()];
  let q = [1, -1];

  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      let diff = p5.Vector.sub(p2[j], p1[i]);
      let d = diff.mag();
      if (d < 15) d = 15;
      let forceMag = (q[i] * q[j] * 600) / sq(d);
      let f = diff.copy().normalize().mult(-forceMag);
      m1.applyForce(f, p1[i]);
      m2.applyForce(f.copy().mult(-1), p2[j]);
    }
  }
}

class Magnet {
  constructor(x, y, angle) {
    this.pos = createVector(x, y);
    this.vel = createVector(random(-1, 1), random(-1, 1));
    this.angle = angle || 0;
    this.angVel = random(-0.02, 0.02);
    this.w = 70;
    this.h = 24;
    this.mass = 2;
  }

  getNorth() {
    return p5.Vector.add(this.pos, createVector(cos(this.angle), sin(this.angle)).mult(this.w * 0.3));
  }

  getSouth() {
    return p5.Vector.add(this.pos, createVector(cos(this.angle), sin(this.angle)).mult(-this.w * 0.3));
  }

  applyForce(f, pt) {
    this.vel.add(p5.Vector.div(f, this.mass));
    let r = p5.Vector.sub(pt, this.pos);
    let torque = r.x * f.y - r.y * f.x;
    this.angVel += torque / 800;
  }

  update() {
    this.vel.mult(0.98);
    this.angVel *= 0.95;
    this.pos.add(this.vel);
    this.angle += this.angVel;

    let pad = this.w / 2;
    if (this.pos.x < pad) { this.pos.x = pad; this.vel.x *= -0.85; }
    if (this.pos.x > width - pad) { this.pos.x = width - pad; this.vel.x *= -0.85; }
    if (this.pos.y < pad) { this.pos.y = pad; this.vel.y *= -0.85; }
    if (this.pos.y > height - pad) { this.pos.y = height - pad; this.vel.y *= -0.85; }
  }

  display() {
    push();
    translate(this.pos.x, this.pos.y);
    rotate(this.angle);

    stroke(255);
    strokeWeight(1.5);

    fill(220, 60, 60);
    rect(this.w / 4, 0, this.w / 2, this.h, 4);

    fill(60, 100, 220);
    rect(-this.w / 4, 0, this.w / 2, this.h, 4);

    fill(255);
    noStroke();
    textSize(12);
    text("N", this.w / 4, 0);
    text("S", -this.w / 4, 0);
    pop();
  }

  contains(x, y) {
    return dist(x, y, this.pos.x, this.pos.y) < this.w / 2;
  }
}

function mousePressed() {
  for (let i = magnets.length - 1; i >= 0; i--) {
    if (magnets[i].contains(mouseX, mouseY)) {
      dragged = magnets[i];
      dragged.vel.set(0, 0);
      dragged.angVel = 0;
      break;
    }
  }
}

function mouseDragged() {
  if (dragged) {
    dragged.pos.set(mouseX, mouseY);
    dragged.vel.set(mouseX - pmouseX, mouseY - pmouseY);
  }
}

function mouseReleased() {
  dragged = null;
}

function keyPressed() {
  if (key === ' ') {
    magnets.push(new Magnet(mouseX, mouseY, random(TWO_PI)));
  }
}

let magnets = [];
let dragged = null;

function setup() {
  createCanvas(800, 600);
  rectMode(CENTER);
  textAlign(CENTER, CENTER);
  for (let i = 0; i < 6; i++) {
    magnets.push(createMagnet(random(150, width - 150), random(150, height - 150), random(TWO_PI)));
  }
}

function draw() {
  background(30, 32, 40);

  for (let i = 0; i < magnets.length; i++) {
    for (let j = i + 1; j < magnets.length; j++) {
      applyMagnetism(magnets[i], magnets[j]);
    }
  }

  for (let m of magnets) {
    if (m !== dragged) {
      updateMagnet(m);
    }
    displayMagnet(m);
  }

  fill(240);
  noStroke();
  textSize(14);
  text("Bouncy Magnets: Click and drag to move, press SPACE to add magnet", width / 2, 25);
}

function createMagnet(x, y, angle) {
  return {
    pos: createVector(x, y),
    vel: createVector(random(-1, 1), random(-1, 1)),
    angle: angle || 0,
    angVel: random(-0.02, 0.02),
    w: 70,
    h: 24,
    mass: 2
  };
}

function getNorth(m) {
  return p5.Vector.add(m.pos, createVector(cos(m.angle), sin(m.angle)).mult(m.w * 0.3));
}

function getSouth(m) {
  return p5.Vector.add(m.pos, createVector(cos(m.angle), sin(m.angle)).mult(-m.w * 0.3));
}

function applyForceToMagnet(m, f, pt) {
  m.vel.add(p5.Vector.div(f, m.mass));
  let r = p5.Vector.sub(pt, m.pos);
  let torque = r.x * f.y - r.y * f.x;
  m.angVel += torque / 800;
}

function applyMagnetism(m1, m2) {
  let p1 = [getNorth(m1), getSouth(m1)];
  let p2 = [getNorth(m2), getSouth(m2)];
  let q = [1, -1];

  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      let diff = p5.Vector.sub(p2[j], p1[i]);
      let d = diff.mag();
      if (d < 15) d = 15;
      let forceMag = (q[i] * q[j] * 600) / sq(d);
      let f = diff.copy().normalize().mult(-forceMag);
      applyForceToMagnet(m1, f, p1[i]);
      applyForceToMagnet(m2, f.copy().mult(-1), p2[j]);
    }
  }
}

function updateMagnet(m) {
  m.vel.mult(0.98);
  m.angVel *= 0.95;
  m.pos.add(m.vel);
  m.angle += m.angVel;

  let pad = m.w / 2;
  if (m.pos.x < pad) { m.pos.x = pad; m.vel.x *= -0.85; }
  if (m.pos.x > width - pad) { m.pos.x = width - pad; m.vel.x *= -0.85; }
  if (m.pos.y < pad) { m.pos.y = pad; m.vel.y *= -0.85; }
  if (m.pos.y > height - pad) { m.pos.y = height - pad; m.vel.y *= -0.85; }
}

function displayMagnet(m) {
  push();
  translate(m.pos.x, m.pos.y);
  rotate(m.angle);

  stroke(255);
  strokeWeight(1.5);

  fill(220, 60, 60);
  rect(m.w / 4, 0, m.w / 2, m.h, 4);

  fill(60, 100, 220);
  rect(-m.w / 4, 0, m.w / 2, m.h, 4);

  fill(255);
  noStroke();
  textSize(12);
  text("N", m.w / 4, 0);
  text("S", -m.w / 4, 0);
  pop();
}

function magnetContains(m, x, y) {
  return dist(x, y, m.pos.x, m.pos.y) < m.w / 2;
}

function mousePressed() {
  for (let i = magnets.length - 1; i >= 0; i--) {
    if (magnetContains(magnets[i], mouseX, mouseY)) {
      dragged = magnets[i];
      dragged.vel.set(0, 0);
      dragged.angVel = 0;
      break;
    }
  }
}

function mouseDragged() {
  if (dragged) {
    dragged.pos.set(mouseX, mouseY);
    dragged.vel.set(mouseX - pmouseX, mouseY - pmouseY);
  }
}

function mouseReleased() {
  dragged = null;
}

function keyPressed() {
  if (key === ' ') {
    magnets.push(createMagnet(mouseX, mouseY, random(TWO_PI)));
  }
}
